-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 2
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 2 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 02', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 02 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-02.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que um requisito precisa ter para ser testável.', 0.2, 'Um requisito testável tem **dado de entrada, condição e resultado verificável** (mensurável), de modo que qualquer pessoa consiga dizer se o sistema atende ou não.', 'Palavras-chave: entrada; condição; resultado verificável/mensurável. Nota cheia (0,2): os três elementos ou a ideia de resultado objetivo verificável. Metade (0,1): só "tem que ser claro" sem a ideia de resultado verificável. Zero (0): "tem que ser curto/bonito".'),
      (v_atividade, 1, 2, 'Diga quais dos três requisitos são vagos e escreva, para cada vago, a pergunta que você faria à equipe.', 0.4, 'Vagos: **R1** ("rápido") e **R2** ("segura"). R3 é testável. Perguntas: R1 — "**Rápido quanto? Em que rede/dispositivo?**"; R2 — "**Quais são as regras da senha (tamanho, números, maiúsculas)?**"', 'Palavras-chave: R1 e R2 vagos; R3 testável; pergunta sobre tempo/rede; pergunta sobre regras. Nota cheia (0,4): identifica R1 e R2 e faz as duas perguntas pertinentes. Metade (0,2): identifica os vagos sem perguntas, ou só um vago com pergunta. Zero (0): classifica R3 como vago e R1/R2 como testáveis.'),
      (v_atividade, 1, 3, 'Reescreva os requisitos vagos de forma testável (com número, regra e resultado verificável) e explique por que a nova escrita permite testar.', 0.4, 'R1: "**O login responde em até 2 s em 4G**". R2: "**Senha com 8 a 64 caracteres, com pelo menos 1 número e 1 letra maiúscula**". Com número e regra, dá para **montar o teste e comparar o resultado obtido com o esperado** (passou/falhou), sem depender de opinião.', 'Palavras-chave: tempo em segundos e rede; tamanho e regras da senha; comparar obtido × esperado/objetivo. Nota cheia (0,4): as duas reescritas com números + explicação. Metade (0,2): uma reescrita boa, ou duas sem explicação. Zero (0): reescritas continuam vagas ("bem rápido", "bem segura").'),
      (v_atividade, 2, 1, 'Escreva os três requisitos testáveis do carrinho com identificador (ex.: RF-10, RF-11, RF-12).', 0.2, '**RF-10:** alterar a quantidade de cada item (de 1 a 10). **RF-11:** subtotal = preço × quantidade de cada item (soma dos itens). **RF-12:** frete grátis se o subtotal for ≥ R$ 199,00.', 'Palavras-chave: alterar quantidade; subtotal = preço × quantidade; frete grátis com valor. Nota cheia (0,2): os três requisitos com ID e regra. Metade (0,1): dois corretos ou três sem regra verificável. Zero (0): copia a especificação sem transformar.'),
      (v_atividade, 2, 2, 'Aponte a lacuna da especificação (o que está faltando ou ambíguo) e explique o risco de começar a programar sem esclarecê-la.', 0.4, 'Lacuna: **não diz o limite (mínimo e máximo) da quantidade** (pode 0? pode 999? estoque?) e não diz se o frete grátis inclui R$ 199,00. Risco: cada pessoa **interpreta de um jeito**, o código sai com um comportamento e o teste espera outro; o defeito só aparece depois e **custa mais caro** corrigir (Myers).', 'Palavras-chave: limite de quantidade ausente (ou ambiguidade do 199); interpretação diferente; defeito/retrabalho; custo maior depois. Nota cheia (0,4): lacuna + risco explicado. Metade (0,2): só a lacuna ou só o risco. Zero (0): diz que não há lacuna.'),
      (v_atividade, 2, 3, 'Diga se "frete grátis acima de R$ 199,00" inclui ou não o valor R$ 199,00, mostre por que isso muda o teste e proponha a escrita final do requisito.', 0.4, '"Acima de R$ 199,00" **não deixa claro** se R$ 199,00 exato tem frete grátis: com "acima" (>) R$ 199,00 **paga** frete; com "a partir de" (≥) **não paga**. O teste do limite R$ 199,00 teria resultados esperados diferentes. Escrita final: "**Frete grátis quando o subtotal for maior ou igual a R$ 199,00**".', 'Palavras-chave: > × ≥; R$ 199,00 exato; resultado esperado muda; escrita final com "maior ou igual"/"a partir de". Nota cheia (0,4): explica a ambiguidade, o impacto no teste e propõe a escrita. Metade (0,2): propõe a escrita sem explicar o impacto, ou explica sem propor. Zero (0): sem relação com o limite.'),
      (v_atividade, 3, 1, 'Liste, em ordem, as 5 atividades do processo fundamental de teste.', 0.2, '1) **Planejamento** (7.1); 2) **Desenho dos testes** (7.2); 3) **Execução** (7.3); 4) **Monitoração e controle** (7.4); 5) **Avaliação dos resultados** (7.5).', 'Palavras-chave: as 5 atividades na ordem. Nota cheia (0,2): as 5 na ordem. Metade (0,1): as 5 fora de ordem ou 3–4 na ordem. Zero (0): 2 ou menos.'),
      (v_atividade, 3, 2, 'Explique o que é feito no planejamento (7.1) e no desenho dos testes (7.2), dando um exemplo de cada para o checkout da loja.', 0.4, '**Planejamento:** define objetivo, escopo, estratégia, recursos, cronograma e riscos — ex.: "testar o checkout com unitários do cálculo do total e 1 E2E da compra, até a aula 6". **Desenho:** transforma requisitos em condições e casos de teste — ex.: "CT-CHK-01: com cupom válido, finalizar a compra mostra a confirmação com o total com desconto".', 'Palavras-chave: planejamento = escopo/estratégia/riscos/cronograma; desenho = requisitos → casos; exemplos do checkout. Nota cheia (0,4): as duas definições com exemplos. Metade (0,2): definições sem exemplos ou um só lado completo. Zero (0): troca planejamento e desenho.'),
      (v_atividade, 3, 3, 'Explique por que começar pela execução, sem planejamento e desenho, é um erro, citando pelo menos duas consequências para o projeto.', 0.4, 'Sem planejamento e desenho, a equipe **testa o que é mais fácil e não o que tem mais risco**, deixa **requisitos sem teste**, **repete esforço**, não sabe **quando parar** nem tem **critério de pronto**; os defeitos de áreas críticas (pagamento) escapam e o custo sobe.', 'Palavras-chave: sem prioridade por risco; requisitos sem teste/lacunas; retrabalho; sem critério/cronograma; defeitos em produção. Nota cheia (0,4): explicação + duas consequências. Metade (0,2): uma consequência. Zero (0): diz que é melhor começar pela execução.'),
      (v_atividade, 4, 1, 'Escreva o escopo e o fora do escopo do plano, com a justificativa do que ficou fora.', 0.2, '**Escopo:** autenticação (login, cadastro, bloqueio), carrinho (quantidade, subtotal, frete) e checkout (cupom, pagamento simulado, confirmação). **Fora do escopo:** integração real com a operadora de cartão, **porque depende de serviço externo** que a equipe não controla (será simulada nos testes).', 'Palavras-chave: as três funcionalidades no escopo; operadora de cartão fora; justificativa (serviço externo). Nota cheia (0,2): escopo + fora do escopo justificado. Metade (0,1): falta a justificativa ou parte do escopo. Zero (0): põe login ou checkout fora do escopo sem justificativa.'),
      (v_atividade, 4, 2, 'Escreva a estratégia (proporção unitário/integração/E2E e as ferramentas) e os ambientes e massa de testes (navegadores, usuários e produtos de teste).', 0.4, '**Estratégia:** base forte de **unitários** (ex.: 70%), **integração** (ex.: 20%) e poucos **E2E** (ex.: 10%); ferramentas **Vitest** (unitários), **Testing Library** (integração) e **Cypress/Playwright** (E2E). **Ambientes e massa:** Chrome, Firefox e um navegador móvel; usuários de teste (ex.: teste@loja.local ativo e um bloqueado); produtos cadastrados com preços para os limites (ex.: R$ 99,50 e R$ 199,00); cupom de teste.', 'Palavras-chave: proporção em pirâmide; ferramentas por camada; navegadores; usuários de teste; produtos de teste. Nota cheia (0,4): estratégia com proporção e ferramentas + ambientes e massa. Metade (0,2): só uma das duas partes completa. Zero (0): pirâmide invertida sem justificativa e sem ambientes.'),
      (v_atividade, 4, 3, 'Escreva as métricas e o cronograma do plano (ligando às aulas 3 a 10) e explique para que servem as métricas.', 0.4, '**Métricas:** cobertura esperada (ex.: ≥ 70%), defeitos encontrados por funcionalidade, testes instáveis. **Cronograma:** aula 3 unitários, aulas 4–5 integração, aula 6 E2E, aula 7 cobertura, aula 8 TDD, aula 9 qualidade e CI, aula 10 suíte final. As métricas servem para **acompanhar o andamento e decidir** (ver se a qualidade está melhorando e onde reforçar).', 'Palavras-chave: cobertura; defeitos; instáveis; cronograma ligado às aulas; acompanhar/decidir. Nota cheia (0,4): métricas + cronograma + para que servem. Metade (0,2): duas das três partes. Zero (0): sem métricas nem cronograma coerentes.'),
      (v_atividade, 5, 1, 'Escreva a fórmula do risco usada no planejamento.', 0.2, '**Risco = probabilidade × impacto.**', 'Palavras-chave: probabilidade; impacto; multiplicação/combinação. Nota cheia (0,2): fórmula correta. Metade (0,1): cita só um dos fatores. Zero (0): outra fórmula.'),
      (v_atividade, 5, 2, 'Registre 3 riscos do projeto com probabilidade, impacto (baixo/médio/alto) e mitigação.', 0.4, 'Exemplos: (1) **cálculo errado do total** — probabilidade média, impacto alto — mitigação: unitários da função de cálculo + 1 E2E do checkout; (2) **login bloqueia usuário válido** — probabilidade baixa, impacto alto — mitigação: casos de borda do bloqueio e integração do formulário; (3) **API de frete fora do ar** — probabilidade média, impacto médio — mitigação: teste com API simulada mostrando aviso sem perder o carrinho.', 'Palavras-chave: 3 riscos; probabilidade; impacto; mitigação. Nota cheia (0,4): 3 riscos com os três campos. Metade (0,2): 2 riscos completos ou 3 sem algum campo. Zero (0): 1 risco ou nenhum coerente.'),
      (v_atividade, 5, 3, 'Justifique tecnicamente, com base no risco, por que o pagamento e o login recebem mais casos e mais camadas de teste que a página "Quem somos".', 0.4, 'O pagamento e o login têm **impacto alto** (cobrança errada, cliente sem acesso, vendas perdidas) e **probabilidade relevante** (muitas regras e integrações), então o **risco é alto** e recebem **mais casos e mais camadas** (unitário, integração e E2E). A página "Quem somos" tem impacto e probabilidade baixos, logo risco baixo e poucos testes. A escolha é **justificada pelo risco**, não por preferência.', 'Palavras-chave: impacto alto; probabilidade; risco alto × baixo; mais casos/camadas; justificativa técnica. Nota cheia (0,4): compara as duas partes pelo risco com consequência no plano. Metade (0,2): fala só de "importância" sem probabilidade/impacto. Zero (0): justificativa sem relação com risco.'),
      (v_atividade, 6, 1, 'Diga qual dos dois testadores fez teste de caixa preta e qual fez teste de caixa branca.', 0.2, 'O testador dos **CEPs (7, 8 e 9 dígitos)** fez **caixa preta**; o que testou os **dois lados do `if`** fez **caixa branca**.', 'Palavras-chave: CEP = caixa preta; if = caixa branca. Nota cheia (0,2): as duas corretas. Metade (0,1): uma correta. Zero (0): invertidas.'),
      (v_atividade, 6, 2, 'Compare as duas técnicas: para o que cada uma olha, qual é a base e quais técnicas usa.', 0.4, '**Caixa preta (3.1):** olha **entradas e saídas sem ver o código**; base: **requisitos e especificação**; técnicas: **partição de equivalência, valores-limite, tabela de decisão**. **Caixa branca (3.2):** olha os **caminhos internos do código**; base: **condições, laços e desvios**; técnicas: **cobertura de instruções e de desvios**.', 'Palavras-chave: sem ver o código × caminhos internos; requisitos × código; técnicas de cada uma. Nota cheia (0,4): os três aspectos das duas. Metade (0,2): dois aspectos ou uma técnica completa só. Zero (0): conceitos trocados.'),
      (v_atividade, 6, 3, 'Escreva os dois testes de caixa branca da função de frete (um para cada lado do if), com o subtotal usado e o frete esperado, e explique o que é cobertura de desvios.', 0.4, 'Lado verdadeiro: subtotal **R$ 199,00** (ou mais) → **frete = 0**. Lado falso: subtotal **R$ 198,99** (ou menos) → **frete = R$ 19,90**. **Cobertura de desvios** é garantir que **cada desvio (lado verdadeiro e lado falso de cada decisão)** foi executado pelo menos uma vez pelos testes.', 'Palavras-chave: subtotal ≥ 199 → 0; subtotal < 199 → 19,90; cada lado do if executado. Nota cheia (0,4): os dois testes + definição. Metade (0,2): os dois testes sem definição, ou definição com um teste. Zero (0): testes que não exercitam os dois lados.'),
      (v_atividade, 7, 1, 'Explique o que é a partição de equivalência e o que são valores-limite.', 0.2, '**Partição de equivalência:** dividir as entradas em **grupos que o sistema trata igual** e testar **um valor de cada grupo**. **Valores-limite:** testar as **bordas** de cada partição (o último valor de um grupo e o primeiro do outro).', 'Palavras-chave: grupos tratados igual; um valor por grupo; bordas. Nota cheia (0,2): os dois conceitos. Metade (0,1): um conceito. Zero (0): nenhum correto.'),
      (v_atividade, 7, 2, 'Liste as partições de equivalência do tamanho da senha, com um valor de exemplo e o resultado esperado de cada uma.', 0.4, '**Curta (< 8):** ex. 5 caracteres → **recusada**. **Válida (8 a 64):** ex. 20 caracteres → **aceita**. **Longa (> 64):** ex. 80 caracteres → **recusada**.', 'Palavras-chave: três partições; exemplo de cada; aceita/recusada. Nota cheia (0,4): as três com exemplo e resultado. Metade (0,2): três sem resultado, ou duas completas. Zero (0): partições sem relação com o tamanho.'),
      (v_atividade, 7, 3, 'Liste os valores-limite que devem ser testados, com o resultado esperado de cada um, e explique por que os defeitos aparecem com mais frequência nas bordas.', 0.4, '**7 → recusada; 8 → aceita; 64 → aceita; 65 → recusada.** Os defeitos aparecem nas bordas porque é ali que o programador **escolhe o operador** (`<` ou `<=`, `>` ou `>=`) e erra por um ("off by one").', 'Palavras-chave: 7, 8, 64, 65 com resultados; operador de comparação/erro por um. Nota cheia (0,4): os quatro valores com resultado + explicação. Metade (0,2): valores sem explicação, ou explicação com valores incompletos. Zero (0): valores do meio (ex.: 30).'),
      (v_atividade, 8, 1, 'Escreva os 3 valores-limite do subtotal para o frete, com o resultado esperado de cada um.', 0.2, '**R$ 198,99 → paga frete; R$ 199,00 → frete grátis; R$ 199,01 → frete grátis.**', 'Palavras-chave: 198,99 paga; 199,00 grátis; 199,01 grátis. Nota cheia (0,2): os três com resultado. Metade (0,1): dois corretos. Zero (0): um ou nenhum.'),
      (v_atividade, 8, 2, 'Escreva as partições e os valores-limite da idade, com o resultado esperado de cada valor.', 0.4, 'Partições: **menor de 16 (recusa)**, **16 a 60 (aceita)**, **maior de 60 (recusa)**. Limites: **15 → recusa; 16 → aceita; 60 → aceita; 61 → recusa.**', 'Palavras-chave: três partições; 15, 16, 60, 61 com resultados. Nota cheia (0,4): partições + quatro limites com resultado. Metade (0,2): só partições ou só limites. Zero (0): valores sem relação com a regra.'),
      (v_atividade, 8, 3, 'Explique por que testar só R$ 50,00 e R$ 500,00 no frete (valores do meio das partições) não seria suficiente e que defeito poderia passar despercebido.', 0.4, 'R$ 50,00 e R$ 500,00 estão **longe da borda**: passam mesmo se o código usar `>` em vez de `>=`. O defeito "**R$ 199,00 exato cobra frete**" (erro de operador) **passaria despercebido**; só o teste no limite o encontra.', 'Palavras-chave: longe da borda; operador > × >=; R$ 199,00 cobrando frete. Nota cheia (0,4): explicação + defeito concreto. Metade (0,2): só "faltou testar o limite" sem o defeito. Zero (0): diz que os dois valores bastam.'),
      (v_atividade, 9, 1, 'Aponte o que falta no caso "CT-01: testar o carrinho" para que outra pessoa consiga executá-lo.', 0.2, 'Faltam **requisito ligado, pré-condição, passos, dados e resultado esperado** (só tem o ID e um título vago); sem isso outra pessoa não sabe o que fazer nem se passou.', 'Palavras-chave: pré-condição; passos; dados; resultado esperado. Nota cheia (0,2): pelo menos três dos campos faltantes, incluindo resultado esperado. Metade (0,1): um ou dois. Zero (0): diz que está completo.'),
      (v_atividade, 9, 2, 'Escreva o caso de teste CT-LOGIN-03 do RF-02 com todos os campos: ID, requisito, pré-condição, passos, dados, resultado esperado e tipo/camada.', 0.4, '**ID:** CT-LOGIN-03 · **Requisito:** RF-02 bloquear após 3 senhas erradas · **Pré-condição:** usuário teste@loja.local cadastrado e desbloqueado · **Passos:** 1. abrir /login; 2. informar o e-mail; 3. errar a senha 3 vezes · **Dados:** senha "errada123" · **Resultado esperado:** mensagem "Acesso bloqueado por 15 minutos" e botão Entrar desabilitado · **Tipo/camada:** funcionalidade (4.1) · E2E.', 'Palavras-chave: os 7 campos. Nota cheia (0,4): 6 ou 7 campos coerentes, com resultado esperado objetivo. Metade (0,2): 4 ou 5 campos, ou resultado esperado vago. Zero (0): 3 ou menos.'),
      (v_atividade, 9, 3, 'Reescreva o mesmo caso no formato BDD (Dado · Quando · Então) e explique a vantagem desse formato para a equipe.', 0.4, '**Dado** que o usuário teste@loja.local está cadastrado e desbloqueado, **Quando** ele erra a senha 3 vezes na tela de login, **Então** vê "Acesso bloqueado por 15 minutos" e o botão Entrar fica desabilitado. Vantagem: linguagem que **toda a equipe entende** (desenvolvimento, testes e negócio), ligando o caso diretamente ao comportamento esperado.', 'Palavras-chave: Dado = pré-condição; Quando = ação; Então = resultado; equipe toda entende. Nota cheia (0,4): BDD correto + vantagem. Metade (0,2): BDD sem vantagem, ou com uma parte trocada. Zero (0): não usa o formato.'),
      (v_atividade, 10, 1, 'Explique o que é uma suíte de testes e como você organizaria a suíte da loja.', 0.2, '**Suíte** é o **conjunto organizado de casos de teste**. Organização: por **funcionalidade** (Autenticação: CT-LOGIN-*; Carrinho: CT-CAR-*; Checkout: CT-CHK-*) ou por **camada** (unitário, integração, E2E).', 'Palavras-chave: conjunto organizado; por funcionalidade ou camada. Nota cheia (0,2): definição + organização. Metade (0,1): só a definição. Zero (0): suíte = um caso único.'),
      (v_atividade, 10, 2, 'Monte a matriz de rastreabilidade requisito × casos com os dados do contexto (uma linha por requisito, incluindo o RF-12).', 0.4, 'Matriz: **RF-01 → CT-LOGIN-01/02**; **RF-02 → CT-LOGIN-03**; **RF-10 → CT-CAR-01**; **RF-11 → CT-CAR-02**; **RF-12 → (nenhum caso)**; **RF-20 → CT-CHK-01**. (Aceitar outra distribuição dos CT-LOGIN entre RF-01 e RF-02 se coerente.)', 'Palavras-chave: uma linha por requisito; casos ligados; RF-12 vazio. Nota cheia (0,4): todos os requisitos com seus casos e RF-12 sem caso. Metade (0,2): matriz incompleta ou sem o RF-12. Zero (0): sem matriz.'),
      (v_atividade, 10, 3, 'Explique o que significa o RF-12 estar sem caso na matriz e escreva o caso que você criaria para ele (ID, dados e resultado esperado).', 0.4, 'RF-12 sem caso é um **requisito sem evidência** de que foi verificado (lacuna de cobertura). Caso: **CT-CAR-03** — dados: subtotais **R$ 198,99, R$ 199,00 e R$ 199,01** — resultado esperado: **paga frete, grátis, grátis**.', 'Palavras-chave: sem evidência/lacuna; caso com ID; valores-limite; resultados. Nota cheia (0,4): significado + caso completo com limites. Metade (0,2): significado com caso sem limites ou sem resultado. Zero (0): diz que não precisa de caso.');
end $$;
